2|
3|import { useCallback, useEffect, useMemo, useRef, useState } from "react";
4|import { nextTrack, parseManifest } from "@/core/music";
5|import type { MusicManifest, SceneSignal, Track } from "@/core/music";
6|import {
7|  initScheduler,
8|  noteTrackEnded,
9|  observeScene,
10|  requestNext,
11|  tickScheduler,
12|} from "@/core/music-schedule";
13|import type { SchedulerState } from "@/core/music-schedule";
14|import { pickActiveScene } from "./active-scene";
15|import { Player } from "./player";
16|
17|export interface SceneMeta {
18|  id: string;
19|  title: string;
20|  emotion: SceneSignal | null;
21|}
22|
23|// Client container: tracks the active scene, runs the pure scheduler
24|// with wall-clock seconds, and passes the chosen track to the player.
25|export function Reader({ scenes, children }: { scenes: SceneMeta[]; children: React.ReactNode }) {
26|  const [activeId, setActiveId] = useState<string | null>(scenes[0]?.id ?? null);
27|  const [manifest, setManifest] = useState<MusicManifest | null>(null);
28|  const [musicFailed, setMusicFailed] = useState(false);
29|  const [currentId, setCurrentId] = useState<string | null>(null);
30|  const [fadeSec, setFadeSec] = useState(0);
31|  const byId = useMemo(() => new Map(scenes.map((s) => [s.id, s])), [scenes]);
32|  const schedRef = useRef<SchedulerState>(initScheduler());
33|  const liveRef = useRef({ activeId, manifest, currentId, byId });
34|  liveRef.current = { activeId, manifest, currentId, byId };
35|
36|  const nowSec = () => Date.now() / 1000;
37|
38|  const applyDecision = useCallback((decision: {
39|    state: SchedulerState;
40|    switchToId: string | null;
41|    crossfadeSec: number;
42|  }) => {
43|    schedRef.current = decision.state;
44|    setActiveId(decision.state.activeSceneId);
45|    if (decision.switchToId !== null) {
46|      setCurrentId(decision.switchToId);
47|      setFadeSec(decision.crossfadeSec);
48|    }
49|  }, []);
50|
51|  const observe = useCallback(
52|    (sceneId: string) => {
53|      const st = liveRef.current;
54|      if (!st.manifest) return;
55|      const signal = st.byId.get(sceneId)?.emotion ?? null;
56|      applyDecision(observeScene(schedRef.current, sceneId, signal, st.manifest, nowSec()));
57|    },
58|    [applyDecision],
59|  );
60|
61|  useEffect(() => {
62|    let cancelled = false;
63|    fetch("/music/manifest.json")
64|      .then((res) => {
65|        if (!res.ok) throw new Error(`manifest ${res.status}`);
66|        return res.json();
67|      })
68|      .then((json: unknown) => {
69|        if (cancelled) return;
70|        setManifest(parseManifest(json));
71|      })
72|      .catch(() => {
73|        if (!cancelled) setMusicFailed(true);
74|      });
75|    return () => {
76|      cancelled = true;
77|    };
78|  }, []);
79|
80|  // Reselect once the manifest lands so the first scene gets music.
81|  useEffect(() => {
82|    if (!manifest) return;
83|    const st = liveRef.current;
84|    if (st.activeId) observe(st.activeId);
85|  }, [manifest, observe]);
86|
87|  useEffect(() => {
88|    const snapshot = () =>
89|      [...document.querySelectorAll<HTMLElement>("section[data-scene-id]")].map((el) => ({
90|        id: el.dataset.sceneId ?? "",
91|        top: el.getBoundingClientRect().top,
92|      }));
93|    const readActive = () => pickActiveScene(snapshot(), window.innerHeight / 3);
94|    const observer = new IntersectionObserver(
95|      () => {
96|        // Entries are only a trigger; every callback re-snapshots live rects.
97|        const next = readActive();
98|        if (next) observe(next);
99|      },
100|      { rootMargin: "-30% 0px -65% 0px" },
101|    );
102|    document.querySelectorAll("section[data-scene-id]").forEach((el) => observer.observe(el));
103|    const first = readActive();
104|    if (first) observe(first);
105|    const timer = window.setInterval(() => {
106|      // Settle an expired dwell, or re-check the active scene after a hold.
107|      const st = liveRef.current;
108|      if (!st.manifest || !st.activeId) return;
109|      const sceneId = schedRef.current.pendingSceneId ?? st.activeId;
110|      const signal = st.byId.get(sceneId)?.emotion ?? null;
111|      applyDecision(tickScheduler(schedRef.current, signal, st.manifest, nowSec()));
112|    }, 1000);
113|    return () => {
114|      observer.disconnect();
115|      window.clearInterval(timer);
116|    };
117|  }, [observe, applyDecision]);
118|
119|  function skip() {
120|    const st = liveRef.current;
121|    if (!st.manifest || !st.activeId) return;
122|    const signal = st.byId.get(st.activeId)?.emotion ?? null;
123|    applyDecision(requestNext(schedRef.current, signal, st.manifest, nowSec()));
124|  }
125|
126|  function ended(trackId: string) {
127|    const st = liveRef.current;
128|    if (!st.manifest || !st.activeId) return;
129|    const signal = st.byId.get(st.activeId)?.emotion ?? null;
130|    applyDecision(noteTrackEnded(schedRef.current, signal, st.manifest, trackId, nowSec()));
131|  }
132|
133|  const track: Track | null = manifest?.tracks.find((t) => t.id === currentId) ?? null;
134|  const sceneTitle = (activeId && byId.get(activeId)?.title) || null;
135|  const empty = manifest !== null && manifest.tracks.length === 0;
136|  const activeSignal = (activeId && byId.get(activeId)?.emotion) || null;
137|  const canSkip =
138|    manifest !== null &&
139|    manifest.tracks.length > 1 &&
140|    nextTrack(activeSignal ?? null, manifest, currentId) !== null;
141|
142|  return (
143|    <>
144|      <div className="player-bar">
145|        {musicFailed || empty ? (
146|          <p className="player-note">Music unavailable. The reader works without it.</p>
147|        ) : (
148|          <Player
149|            track={track}
150|            fadeSec={fadeSec}
151|            sceneTitle={sceneTitle}
152|            canSkip={canSkip}
153|            onSkip={skip}
154|            onEnded={ended}
155|          />
156|        )}
157|      </div>
158|      {children}
159|    </>
160|  );
