1|"use client";
2|
3|import { useEffect, useRef, useState } from "react";
4|import { MUSIC_CONFIG } from "@/core/music";
5|import type { Track } from "@/core/music";
6|
7|// Two audio elements with equal-power crossfades. Volume lives in a
8|// ref, so the slider never re-runs the track effect or touches src.
9|// Nothing plays before the first user press. Reduced motion only
10|// affects visuals; the audio fade always runs its full length.
11|export function Player({
12|  track,
13|  fadeSec,
14|  sceneTitle,
15|  canSkip,
16|  onSkip,
17|  onEnded,
18|}: {
19|  track: Track | null;
20|  fadeSec: number;
21|  sceneTitle: string | null;
22|  canSkip: boolean;
23|  onSkip: () => void;
24|  onEnded: (trackId: string) => void;
25|}) {
26|  const firstRef = useRef<HTMLAudioElement | null>(null);
27|  const secondRef = useRef<HTMLAudioElement | null>(null);
28|  const audibleRef = useRef(0);
29|  const levelRef = useRef<[number, number]>([1, 0]);
30|  const volumeRef = useRef(0.8);
31|  const fadeRef = useRef<number | null>(null);
32|  const loopArmedRef = useRef<string | null>(null);
33|  const trackRef = useRef<Track | null>(track);
34|  trackRef.current = track;
35|  const fadeSecRef = useRef(fadeSec);
36|  fadeSecRef.current = fadeSec;
37|  const onEndedRef = useRef(onEnded);
38|  onEndedRef.current = onEnded;
39|  const playingRef = useRef(false);
40|  const startedRef = useRef(false);
41|  const [started, setStarted] = useState(false);
42|  const [playing, setPlaying] = useState(false);
43|  const [volume, setVolume] = useState(0.8);
44|  const requestPlayRef = useRef((_: Track, __: number) => {});
45|
46|  const [reducedMotion, setReducedMotion] = useState(
47|    () =>
48|      typeof window !== "undefined" &&
49|      !!window.matchMedia?.("(prefers-reduced-motion: reduce)").matches,
50|  );
51|
52|  useEffect(() => {
53|    const query = window.matchMedia?.("(prefers-reduced-motion: reduce)");
54|    if (!query) return;
55|    const onChange = (event: MediaQueryListEvent) => setReducedMotion(event.matches);
56|    query.addEventListener("change", onChange);
57|    return () => query.removeEventListener("change", onChange);
58|  }, []);
59|
60|  function applyLevels() {
61|    const els = [firstRef.current, secondRef.current];
62|    els.forEach((el, i) => {
63|      if (el) el.volume = Math.min(1, Math.max(0, (levelRef.current[i] ?? 0) * volumeRef.current));
64|    });
65|  }
66|
67|  function cancelFade() {
68|    if (fadeRef.current !== null) {
69|      cancelAnimationFrame(fadeRef.current);
70|      fadeRef.current = null;
71|    }
72|  }
73|
74|  // Assigned each render so handlers always see fresh refs. Fades from
75|  // the currently louder element to the newest track; a mid-fade request
76|  // cancels the pending fade and starts from current levels.
77|  requestPlayRef.current = (next: Track, durSec: number) => {
78|    const els = [firstRef.current, secondRef.current];
79|    const srcIdx = (levelRef.current[0] ?? 0) >= (levelRef.current[1] ?? 0) ? 0 : 1;
80|    const dstIdx = 1 - srcIdx;
81|    const srcEl = els[srcIdx];
82|    const dst = els[dstIdx];
83|    if (!srcEl || !dst) return;
84|    cancelFade();
85|    trackRef.current = next;
86|    loopArmedRef.current = null;
87|    dst.src = next.src;
88|    dst.onloadedmetadata = () => {
89|      if (next.startSec > 0 && Number.isFinite(dst.duration) && next.startSec < dst.duration) {
90|        try {
91|          dst.currentTime = next.startSec;
92|        } catch {
93|          // Past the end; leave playback at zero.
94|        }
95|      }
96|    };
97|    if (!playingRef.current || durSec <= 0) {
98|      levelRef.current = [0, 0];
99|      levelRef.current[dstIdx] = 1;
100|      audibleRef.current = dstIdx;
101|      srcEl.pause();
102|      applyLevels();
103|      if (playingRef.current) void dst.play().catch(() => undefined);
104|      return;
105|    }
106|    if (playingRef.current) void dst.play().catch(() => undefined);
107|    const startSrc = levelRef.current[srcIdx] ?? 0;
108|    const startDst = levelRef.current[dstIdx] ?? 0;
109|    const t0 = performance.now();
110|    const tick = (now: number) => {
111|      const t = Math.min(1, (now - t0) / (durSec * 1000));
112|      levelRef.current[srcIdx] = startSrc * Math.cos((t * Math.PI) / 2);
113|      levelRef.current[dstIdx] = startDst + (1 - startDst) * Math.sin((t * Math.PI) / 2);
114|      applyLevels();
115|      if (t < 1) {
116|        fadeRef.current = requestAnimationFrame(tick);
117|        return;
118|      }
119|      fadeRef.current = null;
120|      levelRef.current[srcIdx] = 0;
121|      levelRef.current[dstIdx] = 1;
122|      audibleRef.current = dstIdx;
123|      applyLevels();
124|      srcEl.pause();
125|    };
126|    fadeRef.current = requestAnimationFrame(tick);
127|  };
128|
129|  const trackId = track?.id ?? null;
130|  useEffect(() => {
131|    const next = trackRef.current;
132|    if (!started || !next) {
133|      // Before the first press, swaps only change src.
134|      if (!started && next) {
135|        const el = [firstRef.current, secondRef.current][audibleRef.current];
136|        if (el && !el.src.endsWith(next.src)) el.src = next.src;
137|      }
138|      return;
139|    }
140|    requestPlayRef.current(next, fadeSecRef.current);
141|  }, [started, trackId]);
142|
143|  useEffect(() => cancelFade, []);
144|
145|  function handleTimeUpdate(index: number, el: HTMLAudioElement) {
146|    const next = trackRef.current;
147|    if (!next || !next.loop || index !== audibleRef.current) return;
148|    const duration = el.duration;
149|    if (!Number.isFinite(duration) || duration <= MUSIC_CONFIG.crossfadeSec * 2) return;
150|    const remain = duration - el.currentTime;
151|    if (remain <= MUSIC_CONFIG.crossfadeSec && loopArmedRef.current !== next.id) {
152|      loopArmedRef.current = next.id;
153|      requestPlayRef.current(next, MUSIC_CONFIG.crossfadeSec);
154|    } else if (remain > MUSIC_CONFIG.crossfadeSec + 1) {
155|      loopArmedRef.current = null;
156|    }
157|  }
158|
159|  function handleEnded(index: number) {
160|    const els = [firstRef.current, secondRef.current];
161|    if (index !== audibleRef.current) {
162|      els[index]?.pause();
163|      return;
164|    }
165|    const next = trackRef.current;
166|    if (!next) return;
167|    if (next.loop) {
168|      requestPlayRef.current(next, MUSIC_CONFIG.crossfadeSec);
169|      return;
170|    }
171|    onEndedRef.current(next.id);
172|  }
173|
174|  function toggle() {
175|    const both = [firstRef.current, secondRef.current];
176|    if (!startedRef.current) {
177|      startedRef.current = true;
178|      setStarted(true);
179|      playingRef.current = true;
180|      setPlaying(true);
181|      const next = trackRef.current;
182|      if (next) requestPlayRef.current(next, 0);
183|      return;
184|    }
185|    if (playingRef.current) {
186|      for (const el of both) el?.pause();
187|      playingRef.current = false;
188|      setPlaying(false);
189|      return;
190|    }
191|    playingRef.current = true;
192|    setPlaying(true);
193|    let heard = false;
194|    both.forEach((el, i) => {
195|      if (el && (levelRef.current[i] ?? 0) > 0.02) {
196|        heard = true;
197|        void el.play().catch(() => undefined);
198|      }
199|    });
200|    const next = trackRef.current;
201|    if (!heard && next) requestPlayRef.current(next, 0);
202|  }
203|
204|  function changeVolume(value: number) {
205|    setVolume(value);
206|    volumeRef.current = value;
207|    applyLevels();
208|  }
209|
210|  const credit = track ? [track.composer, track.artist].filter(Boolean).join(", ") : "";
211|  const detail = track
212|    ? [track.emotion, credit || null, track.license || null].filter(Boolean).join(" · ")
213|    : null;
214|
215|  return (
216|    <div className="player" role="region" aria-label="Music player" data-reduced-motion={reducedMotion}>
217|      <audio ref={firstRef} preload="auto" onTimeUpdate={(e) => handleTimeUpdate(0, e.currentTarget)} onEnded={() => handleEnded(0)} />
218|      <audio ref={secondRef} preload="auto" onTimeUpdate={(e) => handleTimeUpdate(1, e.currentTarget)} onEnded={() => handleEnded(1)} />
219|      <button type="button" onClick={toggle} aria-label={playing ? "Pause music" : "Play music"}>
220|        {playing ? "Pause" : "Play"}
221|      </button>
222|      <span className="player-track" aria-live="polite">
223|        {track ? track.title : "Music unavailable"}
224|        {detail ? ` · ${detail}` : ""}
225|        {sceneTitle ? ` · ${sceneTitle}` : ""}
226|      </span>
227|      <label className="player-volume">
228|        Volume
229|        <input
230|          type="range"
231|          min={0}
232|          max={1}
233|          step={0.05}
234|          value={volume}
235|          onChange={(e) => changeVolume(Number(e.target.value))}
236|          aria-label="Volume"
237|        />
238|      </label>
239|      <button type="button" onClick={onSkip} disabled={!canSkip} aria-label="Change track">
240|        Change track
241|      </button>
242|      {track?.attribution ? <span className="player-note">{track.attribution}</span> : null}
243|      {track?.sourceUrl ? (
244|        <a className="player-note" href={track.sourceUrl} rel="noopener noreferrer" target="_blank">
245|          Source
246|        </a>
247|      ) : null}
248|    </div>
249|  );
