291|    }
292|    return {
293|      id,
294|      src,
295|      title,
296|      emotion,
297|      vector,
298|      intensity,
299|      tempo,
300|      durationSec,
301|      startSec: start,
302|      loop: loops,
303|      ...credit,
304|      ...(trackSource === undefined ? {} : { source: trackSource }),
305|      ...(sourceUrl === undefined ? {} : { sourceUrl }),
306|    };
307|  });
308|  return { version: SUPPORTED_VERSION, tracks };
