const manifest: any = { version: 2, tracks: [track("sad-a","tristeza"), track("sad-b","tristeza",0.6), track("sad-c","tristeza",0.9,0.9), track("calm","calma",0.2,0.2), track("tense","suspenso",0.6,0.6)] };
for (let w = 0; w <= 1.001; w += 0.02) {
  for (const inten of [0.2, 0.35, 0.5, 0.65, 0.8]) {
    const v: any = {};
    for (const id of EMOTIONS) v[id] = (base("tristeza") as any)[id] * (1 - w) + (base("calma") as any)[id] * w;
    const s: any = { vector: v, intensity: inten, tempo: 0.5 };
    if (dominantEmotion(s) !== "tristeza") continue;
    const ranked = rankTracks(s, manifest);
    const best = ranked[0];
    if (best.emotion === "tristeza") continue; // need best of another emotion
    const nx = nextTrack(s, manifest, best.id); // starts at top tristeza candidate
    if (!nx || nx.id === best.id) continue;
    const gap = scoreTrack(s, best) - scoreTrack(s, nx);
    console.log(`w=${w.toFixed(2)} i=${inten} best=${best.id} next=${nx.id} gap=${gap.toFixed(3)} hard=${MUSIC_CONFIG.hardCutMargin} margin=${MUSIC_CONFIG.switchMargin}`);
    if (gap >= MUSIC_CONFIG.switchMargin) {
      const st: any = { currentId: best.id, currentStartedSec: 0, activeSceneId: "s1", pendingSceneId: null, pendingSinceSec: 0, overrideId: null, overrideSceneId: null };
      const d = requestNext(st, s, manifest, 100);
      console.log(" after Next: current=", d.state.currentId);
      const t1 = tickScheduler(d.state, s, manifest, 101);
      console.log(" tick@101: switchToId=", t1.switchToId, "hardCut=", t1.hardCut, "crossfade=", t1.crossfadeSec);
      process.exit(0);
    }
  }
}
console.log("NO-CASE");
EOF
